// macOS bundle icon from a source SVG. Generated bytes stay out of the checkout.
// Linux and Windows packages do not use icns; iconutil exists only on macOS.
import { mkdirSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { execFileSync } from 'node:child_process';

export function writeIcns(svg, output) {
  if (process.platform !== 'darwin') {
    throw new Error('icns generation uses iconutil and is only available on macOS.');
  }
  const iconset = join(tmpdir(), `pero-icon-${process.pid}.iconset`);
  rmSync(iconset, { recursive: true, force: true });
  mkdirSync(iconset);
  mkdirSync(dirname(output), { recursive: true });
  try {
    for (const size of [16, 32, 128, 256, 512]) {
      for (const scale of [1, 2]) {
        execFileSync('rsvg-convert', [
          '--width', String(size * scale),
          '--height', String(size * scale),
          '--output', join(iconset, `icon_${size}x${size}${scale === 2 ? '@2x' : ''}.png`),
          svg,
        ]);
      }
    }
    execFileSync('/usr/bin/iconutil', ['--convert', 'icns', '--output', output, iconset]);
  } finally {
    rmSync(iconset, { recursive: true, force: true });
  }
}
